import{_ as t,o as r,c as d,a2 as o}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"開発者ガイド","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/dev-guide/index.md","filePath":"ja-JP/dev-guide/index.md","lastUpdated":1788250223000}'),a={name:"ja-JP/dev-guide/index.md"};function c(i,e,l,n,s,h){return r(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="開発者ガイド" tabindex="-1">開発者ガイド <a class="header-anchor" href="#開発者ガイド" aria-label="Permalink to &quot;開発者ガイド&quot;">​</a></h1><p>Lertaro 開発者向けリファレンスマニュアルへようこそ。Lertaro は疎結合なマルチプロセスアーキテクチャと拡張性の高いプラグインエコシステムを採用しており、公式 SDK アセンブリ <code>Lertaro.PluginSdk</code> を提供しています。この SDK を参照することで、カスタム検索ソースの追加、コンテキストメニューアクションの拡張、サードパーティ製ファイラーや標準ファイルダイアログとの高度な統合、テーマやファイルプレビューのカスタマイズが可能です。</p><h2 id="_1-アーキテクチャと開発フロー" tabindex="-1">1. アーキテクチャと開発フロー <a class="header-anchor" href="#_1-アーキテクチャと開発フロー" aria-label="Permalink to &quot;1. アーキテクチャと開発フロー&quot;">​</a></h2><ul><li><strong><a href="./architecture.html">システムアーキテクチャ設計</a></strong> —— SYSTEM 権限の Windows サービス、ユーザー権限の WPF UI、キーボードフックプロセスの 3 プロセス分離モデルと名前付きパイプ IPC の詳細。</li><li><strong><a href="./getting-started.html">クイックスタートガイド</a></strong> —— クラスライブラリの作成、SDK の参照、<code>IPlugin</code> エントリポイントの実装、ローカルデバッグの手順。</li><li><strong><a href="./packaging.html">パッケージングと配布</a></strong> —— ディレクトリ構造の仕様、依存ライブラリの同梱、多言語 JSON リソースの埋め込み、PostBuild 自動配置。</li><li><strong><a href="./examples.html">公式プラグインのサンプル解説</a></strong> —— オープンソースとして同梱されている <code>CoreExtensions</code>、<code>PinyinAlias</code>、<code>FlowLauncherBridge</code> の設計と実装パターンの詳細解説。</li></ul><h2 id="_2-プラグイン-sdk-api-リファレンス" tabindex="-1">2. プラグイン SDK API リファレンス <a class="header-anchor" href="#_2-プラグイン-sdk-api-リファレンス" aria-label="Permalink to &quot;2. プラグイン SDK API リファレンス&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">SDK カテゴリ</th><th style="text-align:left;">主要インターフェイス・サービス</th><th style="text-align:left;">主な機能</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./sdk/core-search-actions.html">検索コアとアクション</a></strong></td><td style="text-align:left;"><code>ISearchableItemProvider</code><br><code>IInstantResultProvider</code><br><code>IAliasProvider</code><br><code>IQueryTokenProvider</code><br><code>ISearchResultAction</code><br><code>IDynamicActionProvider</code></td><td style="text-align:left;">静的インデックスソース、即時計算クエリ、非 ASCII エイリアス変換エンジン、末尾属性トークンハンドラー、静的・動的コンテキストメニュー。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/system-adapters.html">システムとダイアログの統合</a></strong></td><td style="text-align:left;"><code>IActivePathCollector</code><br><code>IFileDialogAdapter</code><br><code>IInlineSearchAdapter</code><br><code>IQuickNavigationProvider</code></td><td style="text-align:left;">アクティブなファイラーのパス取得、標準ファイルダイアログのフック、インライン検索バーの埋め込みと双方向選択同期、クイックナビゲーションメニュー。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/ui-extensions.html">UI とプレビューの拡張</a></strong></td><td style="text-align:left;"><code>ISidebarFilterProvider</code><br><code>IResultColumnProvider</code><br><code>IQuickPanelTabProvider</code><br><code>IFilePreviewProvider</code><br><code>IThumbnailProvider</code><br><code>IThemeProvider</code><br><code>ITranslationProvider</code></td><td style="text-align:left;">サイドバーフィルターカテゴリ、テーブル列の拡張、クイックパネルの動的タブ、QuickLook プレビュー描画、サムネイル抽出、WPF テーマ、多言語 i18n。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/abstractions.html">共通データ構造と契約</a></strong></td><td style="text-align:left;"><code>ISearchResult</code><br><code>FileMetadata</code><br><code>IPluginSearchWindow</code><br><code>IConfigurable</code></td><td style="text-align:left;">検索結果の読み取り専用モデル、高精度ファイルメタデータ、親ウィンドウの制御ハンドル、スキーマ駆動型ネイティブ設定フォーム。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/services.html">ホストが提供する各種サービス</a></strong></td><td style="text-align:left;"><code>FuzzyMatchService</code><br><code>TranslationService</code><br><code>IconService</code><br><code>FavoritesService</code><br><code>HistoryService</code><br><code>FileMetadataService</code><br><code>DirectoryIndexerService</code><br><code>RecentFilesService</code><br><code>ExplorerPathService</code><br><code>PluginSettingsService</code><br><code>SettingsSearchService</code><br><code>SettingsWindowService</code><br><code>SearchRefreshService</code><br><code>UserDataService</code><br><code>Logger</code></td><td style="text-align:left;">高性能ホスト機能：fzf あいまい一致とハイライトマスク、多言語解析、キャッシュ付きアイコン抽出、お気に入り管理・履歴取得、インデックスサービス連携、データ分離、Shell ファイル操作。</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>本マニュアルのすべてのインターフェイス定義、引数、動作仕様は <code>Lertaro.PluginSdk</code> のソースコードに基づいて厳密に記述されています。</p></div>',7)])])}const S=t(a,[["render",c]]);export{b as __pageData,S as default};
